#!/usr/bin/env python3
"""Build the self-contained CMSMotive static-site HTML pages."""
from pathlib import Path

ROOT = Path(__file__).parent
IMG = "assets/images/"
ICON = "assets/icons/"


def arrow(up=False):
    file = "arrow-up-right.svg" if up else "arrow-right.svg"
    return f'<img src="{ICON}{file}" alt="" width="16" height="16">'


def btn(label, href, kind="primary", up=False):
    return f'<a class="btn btn-{kind}" href="{href}"><span class="btn-label">{label}</span><span class="btn-icon" aria-hidden="true">{arrow(up)}</span></a>'


def text_link(label, href):
    return f'<a class="text-link" href="{href}">{label}{arrow()}</a>'


def logo(location):
    if location == "footer":
        src, w, h = f"{IMG}logo-dark.png", 180, 60
    else:
        src, w, h = f"{IMG}logo.png", 144, 48
    return f'<a class="logo logo-{location}" href="index.html" aria-label="CMSMotive home"><img src="{src}" alt="CMSMotive" width="{w}" height="{h}"></a>'


def browser(image="nordform-architecture.webp", detail=False):
    image_class = "preview-image-index" if image == "hero-typo3-template-v1.webp" else "preview-image-nordform"
    return f'''<div class="browser {'detail-browser' if detail else ''}" aria-label="Nordform theme visual concept preview">
      <div class="browser-bar"><i></i><i></i><i></i><span class="browser-url">nordform.cmsmotive — visual preview</span></div>
      <div class="preview-site"><div class="preview-head"><span class="preview-word">NORDFORM<span class="preview-word-dot">.</span></span><span class="preview-menu"><span>Projects</span><span>Practice</span><span>Journal</span><span>Contact ↗</span></span></div>
      <div class="preview-image {image_class}"><div class="preview-overlay"><small>Architecture / Urban life / Form</small><strong>Ideas made<br>to last.</strong><span>Explore our work &nbsp; ↗</span></div></div></div>
    </div>'''


def product_card(name, category, image, description, badges, price, href, label="Theme concept"):
    chips = ''.join(f'<span class="badge {cls}">{text}</span>' for text, cls in badges)
    image_alts = {"nordform-architecture.webp": "Contemporary pale concrete architecture", "foundation-studio.webp": "Designer working in a bright architecture studio", "campus-library.webp": "Students outside a modern brick and glass campus library"}
    display_price = f'€{price}' if price else ('Free' if price == 0 else 'TBD')
    price_label = 'Preview price' if price else ('Planned price' if price == 0 else 'Roadmap price')
    return f'''<article class="product-card" data-product data-name="{name.lower()}" data-industry="{category.lower()}" data-price="{price if price is not None else -1}" data-version="13 14" data-reveal>
      <a class="product-visual" href="{href}" aria-label="Explore {name}"><img src="{IMG}{image}" width="1536" height="1024" loading="lazy" alt="{image_alts[image]}"><span class="visual-label">{label}</span></a>
      <div class="product-body"><span class="product-kicker">{category}</span><h3>{name}</h3><p>{description}</p><div class="badge-row">{chips}</div><div class="product-bottom"><span class="product-price"><small>{price_label}</small>{display_price}</span>{text_link('Explore theme',href)}</div></div>
    </article>'''


def section_title(kicker, title, description="", more=""):
    return f'''<div class="section-heading" data-reveal><div><span class="eyebrow">{kicker}</span><h2>{title}</h2></div>{'<div><p>'+description+'</p>'+more+'</div>' if description or more else ''}</div>'''


def newsletter():
    """Closing section above the footer; submissions POST to the Next.js /api/newsletter endpoint."""
    return '''<section class="section-sm newsletter-section" aria-labelledby="newsletter-title"><div class="container"><div class="newsletter-card" data-reveal><div class="newsletter-copy"><span class="eyebrow">The Dispatch</span><h2 id="newsletter-title">One email a month, like a good paper.</h2><p>New themes, extension releases and build notes from the CMSMotive workbench — pressed, folded and delivered to your inbox. No spam, unsubscribe any time.</p></div><form class="newsletter-form" data-newsletter-form novalidate><div class="newsletter-fields"><input name="firstName" type="text" placeholder="First name" autocomplete="given-name" aria-label="First name" required><input name="lastName" type="text" placeholder="Last name" autocomplete="family-name" aria-label="Last name" required><input class="newsletter-email" name="email" type="email" placeholder="Email address" autocomplete="email" aria-label="Email address" required><button class="btn btn-primary" type="submit"><span class="btn-label">Subscribe</span><span class="btn-icon" aria-hidden="true">↗</span></button></div><p class="newsletter-status" data-newsletter-status role="status"></p><p class="newsletter-note">We store your name and email only to send the newsletter. See the <a href="privacy.html">privacy policy</a>.</p></form></div></div></section>'''


# Utility bar above the sticky header: contact email, social profiles and the language menu (site.js binds [data-lang-switch]).
# The language links point at each locale's home page; lib/i18n/legacy.ts rewrites them to the current page when serving.
# Kept as a plain string so the generated pages can be patched without re-running this script.
