# Product detail pages: tabbed description / compatibility / reviews / changelog.
# Reviews are loaded from and posted to the Next.js /api/reviews endpoint by
# assets/js/product.js; product slugs must match REVIEW_PRODUCTS in lib/reviews.ts.
PRODUCT_HEAD = '<link rel="stylesheet" href="assets/css/product.css">'
PRODUCT_SCRIPT = '<script src="assets/js/product.js" defer></script>'
CHANGE_KINDS = {"new": "New", "improved": "Improved", "fixed": "Fixed"}
REVIEW_COUNT_CHIP = ' <span class="product-tab-count" data-review-count hidden></span>'


def product_tabs(name, panels):
    """panels: (key, label, html) tuples. Keys are the panel ids, so #reviews deep-links to a tab."""
    buttons, sections = '', ''
    for i, (key, label, html) in enumerate(panels):
        chip = REVIEW_COUNT_CHIP if key == 'reviews' else ''
        buttons += f'<button class="product-tab" type="button" role="tab" id="tab-{key}" aria-controls="{key}" aria-selected="{"true" if i == 0 else "false"}">{label}{chip}</button>'
        sections += f'<section class="product-panel" role="tabpanel" id="{key}" aria-labelledby="tab-{key}">{html}</section>'
    return f'<div class="product-tabs" data-product-tabs><div class="product-tablist" role="tablist" aria-label="{name} details">{buttons}</div>{sections}</div>'


def rating_badge():
    return '<a class="product-rating" href="#reviews" data-review-badge hidden><span class="review-stars" data-review-average-stars role="img" aria-label="Average rating"></span><strong data-review-average>–</strong><span data-review-badge-count>Reviews</span></a>'


def panel_head(eyebrow, title, text=""):
    return f'<div class="product-panel-head"><span class="eyebrow">{eyebrow}</span><h2>{title}</h2>{f"<p>{text}</p>" if text else ""}</div>'


def reviews_panel(slug, name):
    bars = ''.join(f'<li><span>{n} ★</span><span class="review-bar"><i data-review-bar="{n}"></i></span><span data-review-bar-count="{n}">0</span></li>' for n in range(5, 0, -1))
    stars = ''.join(f'<input type="radio" id="rating-{n}" name="rating" value="{n}"><label for="rating-{n}" title="{n} {"star" if n == 1 else "stars"}"><span aria-hidden="true">★</span><span class="review-sr">{n} {"star" if n == 1 else "stars"}</span></label>' for n in range(5, 0, -1))
    form = f'''<div class="contact-form-card review-form-card" id="write-review"><span class="eyebrow">Write a review</span><h2>Share your experience with {name}.</h2><p>No account needed. Reviews are published once our team has approved them, and your email address is never shown.</p>
      <form class="contact-form" data-review-form novalidate>
        <fieldset class="review-rating"><legend>Your rating</legend><div class="review-rating-stars">{stars}</div><span class="review-rating-hint" data-review-rating-hint aria-live="polite"></span></fieldset>
        <div class="contact-form-row"><div class="contact-field"><label for="review-name">Full name</label><input id="review-name" name="name" type="text" autocomplete="name" required minlength="2" maxlength="80" placeholder="First and last name"></div><div class="contact-field"><label for="review-email">Email</label><input id="review-email" name="email" type="email" autocomplete="email" required maxlength="254" placeholder="you@company.com"></div></div>
        <div class="contact-field"><label for="review-body">Your review</label><textarea id="review-body" name="body" required minlength="10" maxlength="2000" rows="5" placeholder="What stood out, and who would you recommend it to?"></textarea><span class="review-counter" data-review-counter aria-hidden="true">0 / 2,000</span></div>
        <div class="review-honeypot" aria-hidden="true"><label for="review-website">Website</label><input id="review-website" name="website" type="text" tabindex="-1" autocomplete="off"></div>
        <p class="review-captcha-note">Protected by Google reCAPTCHA: <a href="https://policies.google.com/privacy" target="_blank" rel="noopener noreferrer">Privacy Policy</a> · <a href="https://policies.google.com/terms" target="_blank" rel="noopener noreferrer">Terms of Service</a></p>
        <div class="contact-form-bottom"><button class="btn btn-primary" type="submit"><span class="btn-label">Submit review</span><span class="btn-icon" aria-hidden="true">{arrow()}</span></button></div>
        <p class="contact-form-status" data-review-status role="status" aria-live="polite" hidden></p>
      </form></div>'''
    return f'''{panel_head('Customer reviews', f'What teams say about {name}.', 'Every review is checked by our team before it is published.')}
    <div class="review-layout" data-reviews data-product="{slug}">
      <aside class="review-summary" aria-label="Rating summary"><div class="review-score"><strong data-review-average>–</strong><span class="review-stars" data-review-average-stars role="img" aria-label="No reviews yet"></span><p data-review-total>No reviews yet</p></div><ul class="review-bars">{bars}</ul><a class="btn btn-outline review-write" href="#write-review"><span class="btn-label">Write a review</span><span class="btn-icon" aria-hidden="true">{arrow()}</span></a></aside>
      <div class="review-feed"><div class="review-empty" data-review-empty hidden><strong>No reviews yet.</strong><p>Be the first to share how {name} works for your team.</p></div><ol class="review-list" data-review-list></ol><button class="btn btn-outline review-more" type="button" data-review-more hidden><span class="btn-label">Show more reviews</span></button></div>
    </div>{form}'''


def changelog_panel(entries, note):
    items = ''
    for version, date_iso, date_label, title, changes in entries:
        lines = ''.join(f'<li><span class="changelog-tag is-{kind}">{CHANGE_KINDS[kind]}</span>{text}</li>' for kind, text in changes)
        items += f'<li class="changelog-entry"><div class="changelog-meta"><span class="changelog-version">{version}</span><time datetime="{date_iso}">{date_label}</time></div><div class="changelog-body"><h3>{title}</h3><ul>{lines}</ul></div></li>'
    return f'{panel_head("Changelog", "Update history.", note)}<ol class="changelog">{items}</ol>'


