def article_page(file, category, title, intro, image, sections):
    paragraphs = ''
    for heading, content in sections:
        paragraphs += f'<h2>{heading}</h2>' + ''.join(f'<p>{p}</p>' for p in content)
    articles = [
        ("blog-typography.html", "Design systems", "Why theme typography should begin with content", "nordform-architecture.webp", "5 min read"),
        ("blog-accessibility.html", "Accessibility", "Accessibility is a product decision", "campus-library.webp", "5 min read"),
        ("blog-composer.html", "Developer workflow", "A calmer Composer-first workflow", "foundation-studio.webp", "5 min read"),
    ]
    popular = ''.join(f'''<a class="popular-item" href="{href}"><img src="{IMG}{cover}" width="96" height="72" loading="lazy" alt=""><span><small>{topic} · {read_time}</small><strong>{headline}</strong><span class="popular-arrow" aria-hidden="true">↗</span></span></a>''' for href, topic, headline, cover, read_time in articles if href != file)
    body = f'''<div class="container blog-detail-shell">
      <div class="crumbs"><a href="index.html">Home</a><span>/</span><a href="blog.html">Journal</a><span>/</span><span>{category}</span></div>
      <div class="blog-detail-grid"><div class="blog-detail-main">
        <article class="content-article"><header class="article-header"><span class="eyebrow">{category}</span><h1>{title}</h1><p class="intro">{intro}</p><div class="article-meta">CMSMotive Editorial &nbsp; · &nbsp; September 2026 &nbsp; · &nbsp; 5 min read</div></header>
          <figure><img src="{IMG}{image}" width="1536" height="1024" alt="Editorial image for article: {title}"><figcaption>CMSMotive editorial image / concept visual</figcaption></figure>
          <div class="article-copy">{paragraphs}<div class="article-callout">The most useful design system is the one a team can understand, change and carry forward.</div></div>
        </article>
        <section class="comments-section" data-comments data-article="{file}" aria-labelledby="comments-title"><div class="comments-heading"><div><span class="eyebrow">The conversation</span><h2 id="comments-title">Comments <span data-comment-count>0</span></h2></div><p>Share a thought or continue a thread.</p></div>
          <div class="comment-list" data-comment-list><p class="comment-empty">Loading comments…</p></div>
          <div class="comment-composer"><h3>Leave a comment</h3><p>Comments in this static preview are saved only in this browser.</p><form class="comment-form" data-comment-form><div class="comment-field"><label for="comment-name">Your name</label><input id="comment-name" name="name" autocomplete="name" required minlength="2" maxlength="60" placeholder="Your name"></div><div class="comment-field"><label for="comment-message">Your comment</label><textarea id="comment-message" name="message" rows="5" required minlength="2" maxlength="2000" placeholder="Add to the conversation..."></textarea></div><div class="comment-form-bottom"><span>Be thoughtful and constructive.</span><button class="btn btn-primary" type="submit"><span class="btn-label">Post comment</span><span class="btn-icon" aria-hidden="true">{arrow()}</span></button></div><p class="comment-status" role="status" aria-live="polite" data-comment-status></p></form></div>
        </section>
      </div><aside class="blog-detail-aside" aria-label="Popular articles"><div class="popular-panel"><span class="eyebrow">From the journal</span><h2>Popular articles</h2><div class="popular-list">{popular}</div><a class="popular-all" href="blog.html">Explore the journal <span aria-hidden="true">↗</span></a></div></aside></div>
      <div class="blog-detail-back">{btn('Back to journal','blog.html','outline')}</div>
    </div>'''
    page(file,title,intro,body,"blog.html",image)

article_page("blog-typography.html","Design systems","Why theme typography should begin with content","A type system earns its place when it can hold the messy, varied material that real editorial teams publish.","nordform-architecture.webp",[("Start with a content inventory",["A theme demo usually shows a perfect headline and two short paragraphs. A production website has long page titles, translations, download tables, author bios and legal text. Collect representative content before you decide what the typography needs to do.","Test the longest realistic title, the smallest useful label and the most complex article page. Those cases tell you more than a pristine hero mockup."]),("Give each role a job",["Display type can set a mood, while body type must stay comfortable through long reading sessions. UI labels need consistency. Code samples need their own rhythm. Use a small set of roles so editors understand what each one is for.","A restrained scale is often more durable than dozens of near-identical sizes. Pair size changes with line length, spacing and weight changes, then check the system at mobile widths."]),("Treat localization as a design test",["A German heading may be substantially longer than an English one. Content can also include accents, numbers and technical terms. Let headings wrap naturally and avoid layout decisions that depend on a fixed number of characters.","In a TYPO3 theme, these rules belong in the component system, not in page-by-page exceptions."])])
article_page("blog-accessibility.html","Accessibility","Accessibility is a product decision","Inclusive behavior is easier to maintain when it shapes templates, components and editorial guidance from the start.","campus-library.webp",[("Begin with the journey",["Think through how someone reaches navigation, opens a menu, reads a form error or moves through a long article without a pointer. These interactions reveal the work an accessibility checklist can miss.","Semantic HTML gives those journeys a strong base. The theme then needs visible focus, sensible heading order and controls that explain their state."]),("Make patterns repeatable",["A carefully built component can give every future page the same keyboard behavior and readable contrast. Documentation should explain what editors can change safely and what content choices can create problems.","Audit results should be tied to a real product version and date. A visual concept is not a conformance statement."]),("Test with people and tools",["Automated checks help catch missing labels and contrast failures. Manual keyboard use, screen reader testing and review of actual content complete the picture. The process should be repeated when templates or dependencies change."])])
article_page("blog-composer.html","Developer workflow","A calmer Composer-first workflow","A dependable theme should be easy to add, inspect, update and hand off to the next developer.","foundation-studio.webp",[("Keep dependencies visible",["Composer makes package versions and requirements part of the project. For an agency team, that visibility helps with review, deployment and maintenance. It also makes upgrades deliberate rather than mysterious.","A package should publish its tested TYPO3 and PHP ranges clearly. The installation guide should say what else needs configuring after the dependency is added."]),("Organize for the next person",["File structure is a form of documentation. Separate configuration, templates and assets in a way that matches how people search for problems. Small, named components are easier to adapt than one highly abstract layer.","Release notes matter just as much as the first install. Teams need to know what changed and whether a migration step is required."]),("Document the real path",["A useful guide covers the ordinary path and the common failure points: missing site configuration, cache behavior, asset builds and deployment. The goal is to help someone finish a project, not simply run one command."])])

about = f'''<section class="page-hero"><div class="container"><div class="crumbs"><a href="index.html">Home</a><span>/</span><span>About</span></div><span class="eyebrow">About CMSMotive</span><h1>Care in the details.<br><em>Clarity in the result.</em></h1><p>CMSMotive is being shaped as an independent product company for the TYPO3 ecosystem: themes, extensions and headless solutions that help teams build with confidence.</p></div></section><section class="section"><div class="container two-col"><div><span class="eyebrow">What we believe</span><h2>Products should respect the work around them.</h2><p class="lead about-lead">Good design gets someone interested. Clear architecture, documentation and predictable maintenance help them keep using it.</p></div><div class="statement-list"><div class="statement"><span class="index">01</span><div><h3>Product before promise</h3><p>Show the interface, the structure and the limitations clearly.</p></div></div><div class="statement"><span class="index">02</span><div><h3>Editor and developer together</h3><p>Make content work pleasant without hiding technical decisions.</p></div></div><div class="statement"><span class="index">03</span><div><h3>Independent by design</h3><p>Respect TYPO3's identity while creating a distinct CMSMotive product language.</p></div></div></div></div></section><section class="section-sm dark-section"><div class="container two-col"><div><span class="eyebrow">Let's build better</span><h2>Have a project in mind?</h2></div><div><p class="lead text-light">Share what your team is building and what you need a TYPO3 product to solve.</p><div class="about-cta">{btn('Get in touch','contact.html','light')}</div></div></div></section>'''
page("about.html", "About", "Learn the principles behind CMSMotive TYPO3 product concepts.", about)

