STATUS_LINKS = [("Themes", "themes.html", "Production-ready TYPO3 themes."), ("Extensions", "extensions.html", "Focused modules for editors."), ("Headless", "headless.html", "TYPO3 content, any frontend."), ("Docs", "docs.html", "Setup guides and references."), ("Contact", "contact.html", "Talk to the team directly.")]
STATUS_CARET = '<span class="status-caret"></span>'
RETRY_ICON = '<svg class="status-retry-icon" viewBox="0 0 16 16" aria-hidden="true"><path d="M13.5 8a5.5 5.5 0 1 1-1.6-3.9"/><path d="M13.5 2.5v3h-3"/></svg>'


def status_window(code, log):
    first, middle, last = code
    rows = ''.join(f'<li><span class="status-log-key">{key}</span><span class="{tone}">{value}{STATUS_CARET if i == len(log) - 1 else ""}</span></li>' for i, (key, value, tone) in enumerate(log))
    return f'''<div class="status-visual" aria-hidden="true"><div class="status-window">
      <div class="status-chrome"><span class="status-lights"><i></i><i></i><i></i></span><span class="status-address">cmsmotive.de<b data-status-path>/</b></span></div>
      <div class="status-stage"><div class="status-code"><span>{first}</span><span class="status-zero">{middle}<span class="status-orbit"></span></span><span>{last}</span></div></div>
      <ul class="status-log">{rows}</ul>
    </div></div>'''


def status_links(label):
    items = ''.join(f'<li><a href="{href}"><span class="status-link-top"><span>{i:02d}</span><img src="{ICON}arrow-up-right.svg" alt="" width="14" height="14"></span><span class="status-link-title">{title}</span><span class="status-link-text">{text}</span></a></li>' for i, (title, href, text) in enumerate(STATUS_LINKS, 1))
    return f'<section class="section-sm"><nav class="container" aria-labelledby="status-links-label"><p class="status-links-label" id="status-links-label">{label}</p><ul class="status-links">{items}</ul></nav></section>'


def status_page(filename, code, title, eyebrow, heading, lead, actions, log, links_label, extra="", tone=""):
    body = f'''<section class="status-hero {tone}" aria-labelledby="status-title"><div class="container status-grid">
      <div class="status-copy"><div class="crumbs"><a href="index.html">Home</a><span>/</span><span>{code}</span></div><span class="eyebrow">{eyebrow}</span><h1 id="status-title">{heading}</h1><p class="status-lead">{lead}</p>{extra}<div class="button-row">{actions}</div></div>
      {status_window(code, log)}
    </div></section>{status_links(links_label)}{STATUS_SCRIPT}'''
    page(filename, title, lead, body, extra_head=STATUS_HEAD)


